package app.fieldwatch

import app.fieldwatch.domain.DefaultCatalog
import app.fieldwatch.domain.DecodeType
import app.fieldwatch.domain.DecodedFieldValue
import app.fieldwatch.domain.Fleet
import app.fieldwatch.domain.resolvedLength

/** UI-only translation of stock authored catalog text. Stored and exported catalogs remain untouched. */
internal object UiCatalogText {
    private val stockById by lazy { DefaultCatalog.fleets().associateBy { it.id } }

    /** Only unchanged stock text is translated; custom signatures and operator edits pass through. */
    fun forFleet(fleet: Fleet?, source: String, translate: (String) -> String = ::text): String {
        if (fleet?.builtIn != true) return source
        val stock = stockById[fleet.id] ?: return source
        if (source == fleet.notes) return if (fleet.notes == stock.notes) translate(source) else source
        if (source == fleet.attentionNote) return if (fleet.attentionNote == stock.attentionNote) translate(source) else source
        if (source == fleet.name) return if (fleet.name == stock.name) translate(source) else source
        val currentFields = fleet.decode?.fields.orEmpty()
        for (field in stock.decode?.fields.orEmpty()) {
            if (field !in currentFields) continue
            if (source == field.label || source in field.enumNotes.orEmpty().values) return translate(source)
            for (value in field.enumLabels.orEmpty().values) {
                if (source == value) return translate(value)
                val unit = field.unit
                if (!unit.isNullOrBlank() && source == "$value $unit") return "${translate(value)} $unit"
            }
        }
        return source
    }

    /** A decoded display may contain arbitrary radio text; only stock enum values are authored text. */
    fun decoded(fleet: Fleet?, row: DecodedFieldValue, translate: (String) -> String = ::text): String {
        if (fleet?.builtIn != true || fleet.id != row.fleetId) return row.display
        val stock = stockById[fleet.id] ?: return row.display
        val currentFields = fleet.decode?.fields.orEmpty()
        for (field in stock.decode?.fields.orEmpty()) {
            if (field !in currentFields || field.id != row.id || field.offset != row.offset ||
                field.resolvedLength() != row.length || field.label != row.label
            ) continue
            val values = field.enumLabels.orEmpty().values.toMutableList()
            if (field.type == DecodeType.BOOL) values.addAll(listOf("yes", "no"))
            val unit = field.unit.orEmpty().trim()
            for (value in values) {
                val display = if (unit.isEmpty()) value else "$value $unit"
                if (row.display == display) {
                    return if (unit.isEmpty()) translate(value) else "${translate(value)} $unit"
                }
            }
        }
        return row.display
    }

